// Process RSS items

function normalizeUrl(url) {
  try {
    const u = new URL(url);
    u.hash = '';
    ['utm_source','utm_medium','utm_campaign','ref'].forEach(k => u.searchParams.delete(k));
    return u.toString().replace(/\/?$/, '/');
  } catch { return url; }
}

function tagsFromText(t) {
  t = (t || '').toLowerCase();
  const tags = [];
  if (/solana|\$sol/.test(t)) tags.push('Chain:Solana');
  if (/ethereum|\$eth/.test(t)) tags.push('Chain:Ethereum');
  if (/arbitrum/.test(t)) tags.push('Chain:Arbitrum');
  if (/polygon|matic/.test(t)) tags.push('Chain:Polygon');
  if (/base chain|base network/.test(t)) tags.push('Chain:Base');
  if (/optimism/.test(t)) tags.push('Chain:Optimism');
  if (/zksync/.test(t)) tags.push('Chain:zkSync');
  if (/\bsui\b/.test(t)) tags.push('Chain:Sui');
  if (/aptos/.test(t)) tags.push('Chain:Aptos');
  if (/bnb|binance/.test(t)) tags.push('Chain:BNB');
  if (/testnet|faucet/.test(t)) tags.push('Type:Testnet');
  if (/mainnet/.test(t)) tags.push('Type:Mainnet');
  if (/stake|staking/.test(t)) tags.push('Type:Stake');
  if (/\bnft\b/.test(t)) tags.push('Type:NFT');
  if (/defi|swap|dex/.test(t)) tags.push('Sector:DeFi');
  if (/gamefi/.test(t)) tags.push('Sector:GameFi');
  if (/layer.?2|\bl2\b/.test(t)) tags.push('Sector:Layer2');
  if (/airdrop/.test(t)) tags.push('Signal:Airdrop');
  if (/retroactive/.test(t)) tags.push('Signal:Retroactive');
  return tags.length ? tags : ['Signal:Airdrop'];
}

function stripHtml(h) { return (h||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim(); }
function truncate(s,n) { s=String(s||'').trim(); return s.length>n ? s.slice(0,n)+'...' : s; }

return items.map(item => {
  const title = truncate(item.json.title, 500);
  const desc = truncate(stripHtml(item.json.content || item.json.description || ''), 2000);
  const src = item.json.link || '';
  if (!src) return null;
  return {
    json: {
      title: title || 'Untitled',
      description: desc || title,
      source_url: src,
      project_url: normalizeUrl(src),
      tags: tagsFromText(title + ' ' + desc),
      status: 'active'
    }
  };
}).filter(Boolean);
